client_script:
// ======================================================
// Payment Entry - سند قبض باستخدام الحقول الحقيقية
// Client Script على Doctype: Payment Entry
// ======================================================

const PAYMENT_VOUCHER_FIELDS = [
  "company",
  "posting_date",
  "mode_of_payment",
  "reference_no",
  "reference_date",
  "party_type",
  "party",
  "paid_from",
  "paid_to",
  "paid_amount",
  "received_amount",
  "custom_remarks",
  "remarks"
];

function get_current_layout_route() {
  return (frappe.router.current_sub_path || "").split("/")[0] || "sanad-qabd";
}

function is_new_voucher(frm) {
  return frm.is_new();
}

function is_submitted_voucher(frm) {
  return frm.doc.docstatus === 1;
}

function hide_all_payment_entry_original_fields(frm) {
  frm.disable_save();

  (frm.meta.fields || []).forEach(df => {
    if (!df.fieldname) return;

    const keep = PAYMENT_VOUCHER_FIELDS.includes(df.fieldname);
    frm.set_df_property(df.fieldname, "hidden", keep ? 0 : 1);
  });

  setTimeout(() => {
    const $wrapper = $(frm.wrapper);

    $wrapper.find(".standard-actions").hide();
    $wrapper.find(".primary-action").hide();
    $wrapper.find(".custom-actions").hide();

    $wrapper.find(".form-section").each(function () {
      if (!$(this).find("#payment-entry-custom-voucher").length) {
        $(this).hide();
      }
    });
  }, 300);
}

function clear_payment_voucher_dashboard(frm) {
  const dashboard = $(frm.wrapper).find(".form-dashboard");
  if (!dashboard.length) return;

  dashboard.find(".frappe-comment").each(function () {
    const $comment = $(this);

    if (
      $comment.find("#payment-entry-custom-voucher").length ||
      ($comment.find(".comment-content").text() || "").includes("Receipt Voucher")
    ) {
      $comment.remove();
    }
  });
}

function get_or_create_payment_voucher_dashboard(frm) {
  let dashboard = $(frm.wrapper).find(".form-dashboard");

  if (!dashboard.length) {
    dashboard = $(`
      <div class="form-dashboard" style="margin-top:20px;">
        <div class="comments-wrapper"></div>
      </div>
    `);

    $(frm.wrapper).find(".form-page").append(dashboard);
  }

  let commentsWrapper = dashboard.find(".comments-wrapper");

  if (!commentsWrapper.length) {
    dashboard.append('<div class="comments-wrapper"></div>');
    commentsWrapper = dashboard.find(".comments-wrapper");
  }

  return commentsWrapper;
}

function render_payment_entry_voucher_layout(frm) {
  if ($(frm.wrapper).find("#payment-entry-custom-voucher").length) return;

  clear_payment_voucher_dashboard(frm);

  const commentsWrapper = get_or_create_payment_voucher_dashboard(frm);

  commentsWrapper.prepend(`
    <div class="frappe-comment payment-voucher-comment" style="margin-bottom:15px;">
      <div class="comment-content">

<style>
  #payment-entry-custom-voucher {
    direction: rtl;
    max-width: 1120px;
    margin: 8px auto;
    background: #fff;
    border-radius: 16px;
    border: 1px solid #e5e7eb;
    overflow: hidden;
    font-family: Tahoma, Arial, sans-serif;
  }

  #payment-entry-custom-voucher .pv-header {
    background: linear-gradient(135deg, #064e3b, #047857);
    padding: 14px 22px;
    text-align: center;
  }

  #payment-entry-custom-voucher .pv-header h2 {
    margin: 0;
    color: #fff;
    font-size: 24px;
    font-weight: 900;
  }

  #payment-entry-custom-voucher .pv-header p {
    margin: 2px 0 0;
    color: #d1d5db;
    font-size: 13px;
  }

  #payment-entry-custom-voucher .pv-body {
    padding: 10px 16px;
  }

  #payment-entry-custom-voucher .pv-summary {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 8px;
    margin-bottom: 8px;
  }

  #payment-entry-custom-voucher .pv-summary-card {
    background: #f9fafb;
    border: 1px solid #e5e7eb;
    border-radius: 12px;
    padding: 8px 12px;
  }

  #payment-entry-custom-voucher .pv-summary-card .label {
    font-size: 13px;
    color: #6b7280;
    margin-bottom: 2px;
  }

  #payment-entry-custom-voucher .pv-summary-card .value {
    font-size: 14px;
    font-weight: 900;
    color: #111827;
  }

  #payment-entry-custom-voucher .pv-section {
    background: #f9fafb;
    border: 1px solid #e5e7eb;
    border-radius: 14px;
    padding: 10px 12px;
    margin-bottom: 8px;
  }

  #payment-entry-custom-voucher .pv-section-title {
    font-size: 15px;
    font-weight: 900;
    color: #111827;
    margin-bottom: 8px;
    padding-bottom: 5px;
    border-bottom: 1px solid #e5e7eb;
  }

  #payment-entry-custom-voucher .pv-grid-3 {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 8px 12px;
  }
    textarea.form-control {
    height: auto;
   }

  #payment-entry-custom-voucher .pv-field-box {
    background: #fff;
    border: 1px solid #eef2f7;
    border-radius: 10px;
    padding: 5px 10px;
    min-height: unset !important;
    height: auto !important;
  }

  #payment-entry-custom-voucher .form-group {
    margin-bottom: 0 !important;
  }

  #payment-entry-custom-voucher .clearfix {
    margin-bottom: 0 !important;
  }

  #payment-entry-custom-voucher .control-label {
    margin-bottom: 2px !important;
    font-size: 13px !important;
    font-weight: 800 !important;
    line-height: 1.2 !important;
  }

  #payment-entry-custom-voucher .control-input-wrapper {
    margin: 0 !important;
    padding: 0 !important;
  }

  #payment-entry-custom-voucher .control-input {
    margin: 0 !important;
    min-height: 30px !important;
  }

  #payment-entry-custom-voucher input,
  #payment-entry-custom-voucher select {
    height: 30px !important;
    min-height: 30px !important;
    padding-top: 4px !important;
    padding-bottom: 4px !important;
    font-size: 12px !important;
  }

  #payment-entry-custom-voucher textarea {
    min-height: 38px !important;
    height: 38px !important;
    font-size: 13px !important;
  }

  #payment-entry-custom-voucher .pv-actions {
    display: flex;
    justify-content: center;
    gap: 8px;
    margin-top: 10px;
    flex-wrap: wrap;
  }

  #payment-entry-custom-voucher .pv-actions .btn {
    min-width: 140px;
    padding: 7px 18px;
    border-radius: 9px;
    font-weight: 900;
  }

  .pv-table-wrap {
    overflow-x: auto;
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 12px;
  }

  .pv-table {
    width: 100%;
    border-collapse: collapse;
    min-width: 760px;
  }

  .pv-table th,
  .pv-table td {
    padding: 7px 9px;
    border-bottom: 1px solid #eef2f7;
    text-align: right;
    font-size: 12px;
  }

  .pv-table th {
    background: #f3f4f6;
    color: #111827;
    font-weight: 900;
  }

  .pv-badge {
    display: inline-block;
    padding: 3px 8px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 800;
  }

  .pv-badge-draft {
    background: #fff7ed;
    color: #c2410c;
  }

  .pv-badge-submit {
    background: #ecfdf5;
    color: #047857;
  }

  .pv-empty {
    text-align: center;
    color: #6b7280;
    padding: 10px;
    font-size: 13px;
  }
#payment-entry-custom-voucher .pv-grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px 12px;
}
#payment-entry-custom-voucher .pv-grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px 12px;
}
  @media (max-width: 768px) {
    #payment-entry-custom-voucher .pv-summary,
    #payment-entry-custom-voucher .pv-grid-3 {
      grid-template-columns: 1fr;
    }
  }
</style>

        <div id="payment-entry-custom-voucher">
          <div class="pv-header">
            <h2>سند قبض</h2>
            <p>Receipt Voucher</p>
          </div>

          <div class="pv-body">

            <div class="pv-section">
              <div class="pv-section-title">بيانات السند</div>
              <div class="pv-grid-3">
                <div class="pv-field-box" id="pv_company"></div>
                <div class="pv-field-box" id="pv_posting_date"></div>
                <div class="pv-field-box" id="pv_mode_of_payment"></div>
                <div class="pv-field-box" id="pv_reference_no"></div>
                <div class="pv-field-box" id="pv_reference_date"></div>
              </div>
            </div>

            <div class="pv-section">
              <div class="pv-section-title">بيانات الدافع</div>
              <div class="pv-grid-3">
                <div class="pv-field-box" id="pv_party_type"></div>
                <div class="pv-field-box" id="pv_party"></div>
              </div>
            </div>

            <div class="pv-section">
              <div class="pv-section-title">بيانات الحسابات والمبلغ</div>
              <div class="pv-grid-4">
                <div class="pv-field-box" id="pv_paid_from"></div>
                <div class="pv-field-box" id="pv_paid_to"></div>
                <div class="pv-field-box" id="pv_paid_amount"></div>
                <div class="pv-field-box" id="pv_received_amount"></div>
              </div>
            </div>

            <div class="pv-section">
              <div class="pv-section-title">البيان</div>
              <div class="pv-grid-1">
                <div class="pv-field-box" id="pv_remarks"></div>
              </div>
            </div>

            <div class="pv-actions">
              <button class="btn btn-primary" id="pv_save_btn">حفظ السند</button>
              <button class="btn btn-warning" id="pv_edit_btn" style="display:none;">تعديل</button>
              <button class="btn btn-success" id="pv_update_btn" style="display:none;">حفظ التعديل</button>
            </div>

            <div class="pv-section" id="pv_my_vouchers_section">
              <div class="pv-section-title">سندات القبض الخاصة بي</div>
              <div id="pv_my_vouchers_table" class="pv-table-wrap">
                <div class="pv-empty">جاري تحميل السندات...</div>
              </div>
            </div>

          </div>
        </div>

      </div>
    </div>
  `);

  setTimeout(() => {
    mount_payment_entry_real_fields(frm);

    if (frm.is_new()) {
      load_my_payment_vouchers();
    }
  }, 600);
}

function move_real_payment_field(frm, fieldname, target_id) {
  const field = frm.fields_dict[fieldname];
  const $target = $("#" + target_id);

  if (!field || !field.$wrapper || !$target.length) return;

  field.$wrapper.detach().appendTo($target);
  field.$wrapper.show();

  field.df.hidden = 0;
  field.refresh();

  frm.set_df_property(fieldname, "hidden", 0);
}

function set_payment_voucher_readonly(frm, readonly) {
  PAYMENT_VOUCHER_FIELDS.forEach(fieldname => {
    if (!frm.fields_dict[fieldname]) return;

    frm.set_df_property(fieldname, "read_only", readonly ? 1 : 0);
    frm.fields_dict[fieldname].refresh();
  });
}

function mount_payment_entry_real_fields(frm) {
  if (!$("#payment-entry-custom-voucher").length) return;

  move_real_payment_field(frm, "company", "pv_company");
  move_real_payment_field(frm, "posting_date", "pv_posting_date");
  move_real_payment_field(frm, "mode_of_payment", "pv_mode_of_payment");
  move_real_payment_field(frm, "reference_no", "pv_reference_no");
  move_real_payment_field(frm, "reference_date", "pv_reference_date");

  move_real_payment_field(frm, "party_type", "pv_party_type");
  move_real_payment_field(frm, "party", "pv_party");

  move_real_payment_field(frm, "paid_from", "pv_paid_from");
  move_real_payment_field(frm, "paid_to", "pv_paid_to");
  move_real_payment_field(frm, "paid_amount", "pv_paid_amount");
  move_real_payment_field(frm, "received_amount", "pv_received_amount");

  move_real_payment_field(frm, "remarks", "pv_remarks");

  set_default_payment_voucher_values(frm);
  bind_payment_voucher_buttons(frm);
  update_payment_voucher_buttons(frm);
}

function set_default_payment_voucher_values(frm) {
  if (frm.doc.docstatus === 1) return;

  if (frm.doc.payment_type !== "Receive") {
    frm.set_value("payment_type", "Receive");
  }

  if (frm.doc.mode_of_payment !== "Cash") {
    frm.set_value("mode_of_payment", "Cash");
  }

  if (!frm.doc.custom_remarks) {
    frm.set_value("custom_remarks", 1);
  }

  if (!frm.doc.posting_date) {
    frm.set_value("posting_date", frappe.datetime.get_today());
  }

  if (!frm.doc.reference_date) {
    frm.set_value("reference_date", frappe.datetime.get_today());
  }

  if (!frm.doc.remarks) {
    frm.set_value("remarks", "سند قبض");
  }
}

function update_payment_voucher_buttons(frm) {
  const is_new = frm.is_new();
  const is_submitted = frm.doc.docstatus === 1;

  $("#pv_save_btn").hide();
  $("#pv_edit_btn").hide();
  $("#pv_update_btn").hide();
  $("#pv_my_vouchers_section").hide();

  if (is_new) {
    $("#pv_save_btn").show();
    $("#pv_my_vouchers_section").show();
    set_payment_voucher_readonly(frm, false);
    return;
  }

  if (is_submitted) {
    set_payment_voucher_readonly(frm, true);
    return;
  }

  $("#pv_edit_btn").show();
  set_payment_voucher_readonly(frm, true);
}

function bind_payment_voucher_buttons(frm) {
  $("#pv_save_btn").off("click").on("click", function () {
    frappe.confirm("هل تريد حفظ سند القبض؟", async function () {
      await save_real_payment_voucher(frm);
    });
  });

  $("#pv_edit_btn").off("click").on("click", function () {
    set_payment_voucher_readonly(frm, false);

    $("#pv_edit_btn").hide();
    $("#pv_update_btn").show();

    frappe.show_alert({
      message: "يمكنك الآن تعديل سند القبض",
      indicator: "blue"
    });
  });

  $("#pv_update_btn").off("click").on("click", function () {
    frappe.confirm("هل تريد حفظ التعديل؟", async function () {
      await update_real_payment_voucher(frm);
    });
  });
}

async function validate_payment_voucher(frm) {
  if (!frm.doc.company) frappe.throw("يرجى اختيار الشركة");
  if (!frm.doc.posting_date) frappe.throw("يرجى اختيار تاريخ السند");
  if (!frm.doc.party_type) frappe.throw("يرجى اختيار نوع الدافع");
  if (!frm.doc.party) frappe.throw("يرجى اختيار الدافع");
  if (!frm.doc.paid_from) frappe.throw("يرجى اختيار حساب الدافع");
  if (!frm.doc.paid_to) frappe.throw("يرجى اختيار حساب الصندوق / البنك");

  if (!flt(frm.doc.received_amount || 0) && !flt(frm.doc.paid_amount || 0)) {
    frappe.throw("يرجى إدخال مبلغ صحيح");
  }

  if (!flt(frm.doc.received_amount || 0) && flt(frm.doc.paid_amount || 0)) {
    await frm.set_value("received_amount", frm.doc.paid_amount);
  }

  if (!flt(frm.doc.paid_amount || 0) && flt(frm.doc.received_amount || 0)) {
    await frm.set_value("paid_amount", frm.doc.received_amount);
  }

  if (!frm.doc.reference_no) {
    await frm.set_value("reference_no", `RV-${Date.now()}`);
  }

  if (!frm.doc.reference_date) {
    await frm.set_value("reference_date", frm.doc.posting_date || frappe.datetime.get_today());
  }

  await frm.set_value("payment_type", "Receive");
  await frm.set_value("mode_of_payment", "Cash");
  await frm.set_value("custom_remarks", 1);
}

async function save_real_payment_voucher(frm) {
  try {
    $("#pv_save_btn").prop("disabled", true);

    const current_sub_path = frappe.router.current_sub_path;

    await validate_payment_voucher(frm);
    await frm.save();

    frappe.show_alert({
      message: "تم حفظ سند القبض",
      indicator: "green"
    });

    await load_my_payment_vouchers();

    setTimeout(() => {
      if (current_sub_path) {
        window.location.href = `/app/${current_sub_path}`;
      }
    }, 500);

  } catch (e) {
    console.error(e);

    frappe.msgprint({
      title: "خطأ",
      message: e.message || e,
      indicator: "red"
    });

  } finally {
    $("#pv_save_btn").prop("disabled", false);
  }
}

async function update_real_payment_voucher(frm) {
  try {
    $("#pv_update_btn").prop("disabled", true);

    await validate_payment_voucher(frm);
    await frm.save();

    frappe.show_alert({
      message: "تم حفظ التعديل",
      indicator: "green"
    });

    set_payment_voucher_readonly(frm, true);
    $("#pv_update_btn").hide();
    $("#pv_edit_btn").show();

  } catch (e) {
    console.error(e);

    frappe.msgprint({
      title: "خطأ",
      message: e.message || e,
      indicator: "red"
    });

  } finally {
    $("#pv_update_btn").prop("disabled", false);
  }
}

async function load_my_payment_vouchers() {
  const $box = $("#pv_my_vouchers_table");
  if (!$box.length) return;

  $box.html(`<div class="pv-empty">جاري تحميل السندات...</div>`);

  try {
    const layout_route = get_current_layout_route();

    const rows = await frappe.db.get_list("Payment Entry", {
      fields: [
        "name",
        "posting_date",
        "party_type",
        "party",
        "received_amount",
        "mode_of_payment",
        "docstatus",
        "owner",
        "creation"
      ],
      filters: {
        owner: frappe.session.user,
        payment_type: "Receive",
        custom_remarks: 1
      },
      order_by: "creation desc",
      limit: 10
    });

    if (!rows || !rows.length) {
      $box.html(`<div class="pv-empty">لا توجد سندات قبض خاصة بك</div>`);
      return;
    }

    const htmlRows = rows.map(r => {
      const statusText = r.docstatus === 1 ? "معتمد" : "مسودة";
      const statusClass = r.docstatus === 1 ? "pv-badge-submit" : "pv-badge-draft";

      return `
        <tr>
          <td>
            <a href="/app/${layout_route}/${encodeURIComponent(r.name)}" target="_blank">
              ${frappe.utils.escape_html(r.name)}
            </a>
          </td>
          <td>${frappe.utils.escape_html(r.posting_date || "")}</td>
          <td>${frappe.utils.escape_html(r.party_type || "")}</td>
          <td>${frappe.utils.escape_html(r.party || "")}</td>
          <td>${format_currency(r.received_amount || 0)}</td>
          <td>${frappe.utils.escape_html(r.mode_of_payment || "")}</td>
          <td><span class="pv-badge ${statusClass}">${statusText}</span></td>
        </tr>
      `;
    }).join("");

    $box.html(`
      <table class="pv-table">
        <thead>
          <tr>
            <th>رقم السند</th>
            <th>التاريخ</th>
            <th>نوع الدافع</th>
            <th>الدافع</th>
            <th>المبلغ</th>
            <th>طريقة الدفع</th>
            <th>الحالة</th>
          </tr>
        </thead>
        <tbody>
          ${htmlRows}
        </tbody>
      </table>
    `);

  } catch (e) {
    console.error(e);
    $box.html(`<div class="pv-empty">تعذر تحميل سندات القبض</div>`);
  }
}

function update_received_amount(frm) {
  const rate = frm.doc.source_exchange_rate || 0;
  const trate = frm.doc.target_exchange_rate || 0;
  const paid = frm.doc.paid_amount || 0;

  let received = rate * paid;

  if (trate !== 0) {
    received = received / trate;
  }

  if (frm.doc.payment_type === "Pay") {
    if (frm.doc.received_amount !== received) {
      frm.set_value("received_amount", received);
    }
  }
}

function update_paid_amount(frm) {
  const rate = frm.doc.target_exchange_rate || 0;
  const srate = frm.doc.source_exchange_rate || 0;
  const received = frm.doc.received_amount || 0;

  let paid = rate * received;

  if (srate !== 0) {
    paid = paid / srate;
  }

  if (frm.doc.payment_type === "Receive") {
    if (frm.doc.paid_amount !== paid) {
      frm.set_value("paid_amount", paid);
    }
  }
}

frappe.ui.form.on("Payment Entry", {
  before_load(frm) {
    hide_all_payment_entry_original_fields(frm);
  },

  refresh(frm) {
    hide_all_payment_entry_original_fields(frm);

    setTimeout(() => {
      render_payment_entry_voucher_layout(frm);
    }, 800);
  },
  party_type: function(frm) {
    let mop=frm.doc.mode_of_payment;
    frm.set_value('mode_of_payment', '');
    //frm.refresh_field('mode_of_payment');
    frm.set_value('mode_of_payment', mop);
    //frm.refresh_field('mode_of_payment');
  },

  party(frm) {
    if ((frm.doc.party_type === "Receivable") && frm.doc.party) {
      frappe.db.get_value("Receivable", frm.doc.party, "account", (r) => {
        if (r && r.account) {
          if (frm.doc.payment_type === "Receive") {
            frm.set_value("paid_from", r.account);
          } else if (frm.doc.payment_type === "Pay") {
            frm.set_value("paid_to", r.account);
          }
        }
      });
    }

    if ((frm.doc.party_type === "Payable") && frm.doc.party) {
      frappe.db.get_value("Payable", frm.doc.party, "account", (r) => {
        if (r && r.account) {
          if (frm.doc.payment_type === "Receive") {
            frm.set_value("paid_from", r.account);
          } else if (frm.doc.payment_type === "Pay") {
            frm.set_value("paid_to", r.account);
          }
        }
      });
    }
  },

  paid_amount(frm) {
    update_received_amount(frm);
