function move_real_payment_field(frm, fieldname, target_id) {
  const field = frm.fields_dict[fieldname];
  const $target = $("#" + target_id);

  if (!field || !field.$wrapper || !$target.length) return;

  field.$wrapper.detach().appendTo($target);
  field.$wrapper.show();

  field.df.hidden = 0;
  field.refresh();

  frm.set_df_property(fieldname, "hidden", 0);
}

function set_payment_voucher_readonly(frm, readonly) {
  PAYMENT_VOUCHER_FIELDS.forEach(fieldname => {
    if (!frm.fields_dict[fieldname]) return;

    frm.set_df_property(fieldname, "read_only", readonly ? 1 : 0);
    frm.fields_dict[fieldname].refresh();
  });
}

function mount_payment_entry_real_fields(frm) {
  if (!$("#payment-entry-custom-voucher").length) return;

  move_real_payment_field(frm, "company", "pv_company");
  move_real_payment_field(frm, "posting_date", "pv_posting_date");
  move_real_payment_field(frm, "mode_of_payment", "pv_mode_of_payment");
  move_real_payment_field(frm, "reference_no", "pv_reference_no");
  move_real_payment_field(frm, "reference_date", "pv_reference_date");

  move_real_payment_field(frm, "party_type", "pv_party_type");
  move_real_payment_field(frm, "party", "pv_party");

  move_real_payment_field(frm, "paid_from", "pv_paid_from");
  move_real_payment_field(frm, "paid_to", "pv_paid_to");
  move_real_payment_field(frm, "paid_amount", "pv_paid_amount");
  move_real_payment_field(frm, "received_amount", "pv_received_amount");

  //move_real_payment_field(frm, "custom_remarks", "pv_custom_remarks");
  move_real_payment_field(frm, "remarks", "pv_remarks");

  set_default_payment_voucher_values(frm);
  bind_payment_voucher_buttons(frm);
  update_payment_voucher_buttons(frm);
}

function set_default_payment_voucher_values(frm) {
  if (frm.doc.docstatus === 1) return;

  if (frm.doc.payment_type !== "Pay") {
    frm.set_value("payment_type", "Pay");
  }

  if (frm.doc.mode_of_payment !== "Cash") {
    frm.set_value("mode_of_payment", "Cash");
  }

  if (!frm.doc.custom_remarks) {
    frm.set_value("custom_remarks", 1);
  }

  if (!frm.doc.posting_date) {
    frm.set_value("posting_date", frappe.datetime.get_today());
  }

  if (!frm.doc.reference_date) {
    frm.set_value("reference_date", frappe.datetime.get_today());
  }

  if (!frm.doc.remarks) {
    frm.set_value("remarks", "سند صرف");
  }
}

function update_payment_voucher_buttons(frm) {
  const is_new = frm.is_new();
  const is_submitted = frm.doc.docstatus === 1;

  $("#pv_save_btn").hide();
  $("#pv_edit_btn").hide();
  $("#pv_update_btn").hide();
  $("#pv_my_vouchers_section").hide();

  if (is_new) {
    $("#pv_save_btn").show();
    $("#pv_my_vouchers_section").show();
    $("#pv_status_label").text("جديد");
    set_payment_voucher_readonly(frm, false);
    return;
  }

  if (is_submitted) {
    $("#pv_status_label").text("معتمد");
    set_payment_voucher_readonly(frm, true);
    return;
  }

  $("#pv_status_label").text("محفوظ");
