async function validate_payment_voucher(frm) {
  if (!frm.doc.company) frappe.throw("يرجى اختيار الشركة");
  if (!frm.doc.posting_date) frappe.throw("يرجى اختيار تاريخ السند");
  if (!frm.doc.party_type) frappe.throw("يرجى اختيار نوع المستفيد");
  if (!frm.doc.party) frappe.throw("يرجى اختيار المستفيد");
  if (!frm.doc.paid_from) frappe.throw("يرجى اختيار حساب الصندوق / البنك");
  if (!frm.doc.paid_to) frappe.throw("يرجى اختيار حساب المستفيد");
  if (!flt(frm.doc.paid_amount || 0)) frappe.throw("يرجى إدخال مبلغ صحيح");

  if (!frm.doc.reference_no) {
    await frm.set_value("reference_no", `PV-${Date.now()}`);
  }

  if (!frm.doc.reference_date) {
    await frm.set_value("reference_date", frm.doc.posting_date || frappe.datetime.get_today());
  }

  await frm.set_value("payment_type", "Pay");
  await frm.set_value("mode_of_payment", "Cash");
  await frm.set_value("custom_remarks", 1);
}

async function save_real_payment_voucher(frm) {
  try {
    $("#pv_save_btn").prop("disabled", true);

    const current_sub_path = frappe.router.current_sub_path;

    await validate_payment_voucher(frm);
    await frm.save();

    frappe.show_alert({
      message: "تم حفظ سند الصرف",
      indicator: "green"
    });

    await load_my_payment_vouchers();

    setTimeout(() => {
      if (current_sub_path) {
        window.location.href = `/app/${current_sub_path}`;
      }
    }, 500);

  } catch (e) {
    console.error(e);

    frappe.msgprint({
      title: "خطأ",
      message: e.message || e,
      indicator: "red"
    });

  } finally {
    $("#pv_save_btn").prop("disabled", false);
  }
}

async function update_real_payment_voucher(frm) {
  try {
    $("#pv_update_btn").prop("disabled", true);

    await validate_payment_voucher(frm);
    await frm.save();

    frappe.show_alert({
      message: "تم حفظ التعديل",
      indicator: "green"
    });

    set_payment_voucher_readonly(frm, true);
    $("#pv_update_btn").hide();
    $("#pv_edit_btn").show();

  } catch (e) {
    console.error(e);

    frappe.msgprint({
      title: "خطأ",
      message: e.message || e,
      indicator: "red"
    });

  } finally {
    $("#pv_update_btn").prop("disabled", false);
  }
}

